67	    /** Imports a TensorFlow model */
68	    public TensorFlowModel importModel(SavedModelBundle model) {
69	        try {
70	            return importGraph(MetaGraphDef.parseFrom(model.metaGraphDef()), model);
71	        }
72	        catch (IOException e) {
73	            throw new IllegalArgumentException("Could not import TensorFlow model '" + model + "'", e);
74	        }
75	    }
76	
77	    /**
78	     * Imports the TensorFlow graph by first importing the tensor types, then
79	     * finding a suitable set of dimensions names for each
80	     * placeholder/constant/variable, then importing the expressions.
81	     */
82	    private static TensorFlowModel importGraph(MetaGraphDef graph, SavedModelBundle bundle) {
83	        TensorFlowModel model = new TensorFlowModel();
84	        OperationIndex index = new OperationIndex();
85	
86	        importSignatures(graph, model);
87	        importNodes(graph, model, index);
88	        findDimensionNames(model, index);
89	        importExpressions(model, index, bundle);
90	
91	        reportWarnings(model, index);
92	        logVariableTypes(index);
93	
94	        return model;
95	    }
