102	            Map<String, TensorInfo> inputInfoMap = signatureEntry.getValue().getInputsMap();
103	            for (Map.Entry<String, TensorInfo> input : inputInfoMap.entrySet()) {
104	                String inputName = input.getKey();
105	                signature.input(inputName, namePartOf(input.getValue().getName()));
106	            }
107	
108	            Map<String, TensorInfo> outputInfoMap = signatureEntry.getValue().getOutputsMap();
109	            for (Map.Entry<String, TensorInfo> output : outputInfoMap.entrySet()) {
110	                String outputName = output.getKey();
111	                signature.output(outputName, namePartOf(output.getValue().getName()));
112	            }
113	        }
114	    }
