2	package com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.operations;
3	
4	import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.DimensionRenamer;
5	import com.yahoo.searchlib.rankingexpression.integration.tensorflow.importer.OrderedTensorType;
6	import com.yahoo.tensor.TensorType;
7	import com.yahoo.tensor.functions.TensorFunction;
8	import org.tensorflow.framework.NodeDef;
9	
10	import java.util.List;
11	import java.util.Optional;
12	import java.util.function.DoubleBinaryOperator;
13	
14	public class Join extends TensorFlowOperation {
15	
16	    private final DoubleBinaryOperator operator;
17	
18	    public Join(NodeDef node, List<TensorFlowOperation> inputs, int port, DoubleBinaryOperator operator) {
19	        super(node, inputs, port);
20	        this.operator = operator;
21	    }
22	
23	    @Override
24	    protected OrderedTensorType lazyGetType() {
25	        if (!allInputTypesPresent(2)) {
26	            return null;
27	        }
28	        OrderedTensorType a = inputs.get(0).type().get();
29	        OrderedTensorType b = inputs.get(1).type().get();
30	        OrderedTensorType out = a.type().rank() >= b.type().rank() ? a : b;
31	        return out;
32	    }
33	
34	    @Override
35	    protected TensorFunction lazyGetFunction() {
36	        if (!allInputTypesPresent(2)) {
37	            return null;
38	        }
39	        Optional<TensorFunction> aFunction = inputs.get(0).function();
40	        Optional<TensorFunction> bFunction = inputs.get(1).function();
41	        if (!aFunction.isPresent() || !bFunction.isPresent()) {
42	            return null;
43	        }
44	
45	        // The dimension renaming below takes care of broadcasting.
46	
47	        return new com.yahoo.tensor.functions.Join(aFunction.get(), bFunction.get(), operator);
48	    }
49	
50	    @Override
51	    public void addDimensionNameConstraints(DimensionRenamer renamer) {
52	        if (!allInputTypesPresent(2)) {
53	            return;
54	        }
55	
56	        // Well now we have potentially entered the wonderful world of "broadcasting"
57	        // https://docs.scipy.org/doc/numpy/user/basics.broadcasting.html
58	        // I'm not able to extract from that any unambiguous specification of which dimensions
59	        // should be "stretched" when the tensor do not have the same number of dimensions.
60	        // From trying this with TensorFlow it appears that the second tensor is matched to the
61	        // "end" (highest numbered) dimensions of the first, but I'm not sure whether this is generally true.
62	        // Anyway, we move the dimensions of b to the last dimensions of a (instead of by default, the first).
63	
64	        OrderedTensorType a = inputs.get(0).type().get();
65	        OrderedTensorType b = inputs.get(1).type().get();
66	        if (a.rank() < b.rank()) {
67	            OrderedTensorType temp = a;
68	            a = b;
69	            b = temp;
70	        }
71	        int sizeDifference = a.rank() - b.rank();
72	        for (int i = 0; i < b.rank(); ++i) {
73	            String bDim = b.dimensions().get(i).name();
74	            String aDim = a.dimensions().get(i + sizeDifference).name();
75	            renamer.addConstraint(aDim, bDim, DimensionRenamer::equals, this);
76	        }
77	    }
78	
79	}
